import math

def find_solution(a, b, n):
    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            g, x, y = extended_gcd(b, a % b)
            return (g, y, x - (a // b) * y)

    g, x, y = extended_gcd(a, b)
    if n % g != 0:
        return None
    else:
        x *= n // g
        y *= n // g
        return (x, y)
